from kubernetes import client, config

config.load_kube_config()
apps = client.AppsV1Api()

# List all deployments
# In the sandbox: web-app (default), broken-app (default), api-server (learning),
# argocd-server (argocd), various monitoring deployments
deploys = apps.list_deployment_for_all_namespaces()
for d in deploys.items:
    ns = d.metadata.namespace
    name = d.metadata.name
    desired = d.spec.replicas
    ready = d.status.ready_replicas or 0
    print(f"{ns}/{name}: {ready}/{desired} ready")

# Scale a deployment
apps.patch_namespaced_deployment_scale(
    name="web-app",
    namespace="default",
    body={"spec": {"replicas": 3}}
)

# Restart a deployment (equivalent to kubectl rollout restart)
import datetime
apps.patch_namespaced_deployment(
    name="web-app",
    namespace="default",
    body={
        "spec": {
            "template": {
                "metadata": {
                    "annotations": {
                        "kubectl.kubernetes.io/restartedAt":
                            datetime.datetime.utcnow().isoformat()
                    }
                }
            }
        }
    }
)

# Check rollout status
def is_deployment_ready(name, namespace):
    apps = client.AppsV1Api()
    d = apps.read_namespaced_deployment(name=name, namespace=namespace)
    desired = d.spec.replicas or 0
    ready = d.status.ready_replicas or 0
    updated = d.status.updated_replicas or 0
    return ready == desired == updated and desired > 0

# Try it with the sandbox deployments:
print(is_deployment_ready("web-app", "default"))     # True
print(is_deployment_ready("broken-app", "default"))  # False (crash-looping)
```
